export const GLOSSARY_SHARD = Object.freeze({"market-capitalization":{"slug":"market-capitalization","cat":"basics","en":"Market capitalization","contentLocale":"ko","term":"시가총액(Market Cap)","aka":["시총","Market Cap","마켓캡"],"short":"시가총액은 코인의 현재 가격에 유통 공급량을 곱한 값으로, 시장이 그 자산 전체를 얼마로 평가하고 있는지 보여 주는 지표입니다.","body":[["시가총액은 가격 곱하기 ",["유통량","circulating-supply"],"으로 계산합니다. 코인 하나의 가격만 보면 규모를 알 수 없기 때문에, 서로 다른 코인을 비교할 때는 단가보다 시가총액을 보는 것이 기본입니다. 단가가 1원인 코인도 공급량이 많으면 시가총액은 매우 클 수 있습니다."],["시가총액 순위는 코인 정보 사이트와 ",["거래소","centralized-exchange"]," 앱에서 쉽게 확인할 수 있습니다. 일반적으로 시가총액이 클수록 ",["유동성","liquidity"],"이 풍부하고 가격 변동이 상대적으로 작은 편이지만, 항상 그런 것은 아닙니다."],["주의할 점은 유통량 데이터가 사이트마다 다를 수 있다는 것입니다. 팀 보유 물량이나 잠긴 물량을 어떻게 셀지에 따라 시가총액이 달라지고, ",["거래량","trading-volume"],"이 극히 적은 코인은 시가총액이 커 보여도 실제로 그만큼 팔 수 있다는 뜻은 아닙니다."]],"example":"코인 A는 가격이 0.5달러, 유통량이 40억 개라 시가총액이 20억 달러입니다. 코인 B는 가격이 50달러, 유통량이 1,000만 개라 시가총액이 5억 달러입니다. 단가는 B가 100배 비싸지만 시장 규모는 A가 4배 큽니다. A가 B와 같은 단가 50달러가 되려면 시가총액이 2,000억 달러가 되어야 한다는 계산도 할 수 있습니다.","mistakes":["단가가 낮은 코인은 쉽게 크게 오를 수 있다고 착각하고 시가총액을 보지 않습니다.","시가총액과 완전 희석 가치(FDV)를 같은 숫자로 생각합니다.","시가총액만 보고 실제 거래량과 호가 깊이를 확인하지 않습니다."],"faq":[{"q":"시가총액은 어떻게 계산하나요?","a":"현재 가격에 유통 공급량을 곱해 계산합니다. 예를 들어 가격 2달러, 유통량 1억 개라면 시가총액은 2억 달러입니다."},{"q":"시가총액이 크면 안전한 코인인가요?","a":"규모와 유동성 면에서 유리한 경우가 많지만 안전을 보장하지는 않습니다. 토큰 언락 일정, 거래량, 프로젝트 구조를 함께 봐야 합니다."}],"title":"시가총액(시총)이란? 코인 시총 계산법","description":"코인 시가총액의 뜻과 계산법, 단가보다 시총을 봐야 하는 이유, FDV·유통량 데이터의 차이까지 예시로 설명합니다.","related":[["fully-diluted-valuation","완전 희석 가치(FDV)","완전 희석 가치(FDV)는 코인의 현재 가격에 앞으로 발행될 물량까지 포함한 최대 또는 총 공급량을 곱한 값으로, 모든 토큰이 풀렸을 때의 평가 규모를 보여 줍니다."],["circulating-supply","유통량(Circulating Supply)","유통량은 현재 시장에서 실제로 거래될 수 있는 코인의 수량으로, 잠겨 있거나 아직 발행되지 않은 물량은 제외합니다."],["trading-volume","거래량(Trading Volume)","거래량은 일정 기간 동안 실제로 체결된 코인의 수량 또는 금액을 말하며, 보통 24시간 기준으로 시장의 관심과 활발함을 보여 줍니다."],["tokenomics","토크노믹스(Tokenomics)","토크노믹스는 토큰의 총발행량, 배분 비율, 언락 일정, 사용처, 소각과 인플레이션 규칙 등 토큰의 공급과 수요를 결정하는 경제 구조 전체를 말합니다."],["altcoin","알트코인(Altcoin)","알트코인은 비트코인을 제외한 나머지 암호화폐를 통틀어 부르는 말로, 이더리움, 솔라나, XRP 같은 대형 코인부터 소형 토큰까지 모두 포함합니다."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"market-maker":{"slug":"market-maker","cat":"trading","en":"Market maker","contentLocale":"ko","term":"마켓메이커(Market Maker)","aka":["시장 조성자","MM","market maker"],"short":"마켓메이커는 매수 호가와 매도 호가를 동시에 꾸준히 걸어 두어 다른 사람이 언제든 거래할 수 있도록 유동성을 공급하는 참여자입니다.","body":[["마켓메이커는 보통 ",["현재가","last-price"]," 바로 아래에 매수 주문을, 바로 위에 매도 주문을 걸어 둡니다. 양쪽이 번갈아 체결되면 그 가격 차이인 ",["스프레드","bid-ask-spread"],"만큼 수익을 얻고, ",["메이커 수수료","maker-taker-fees"]," 할인이나 리베이트도 받습니다."],["전문 트레이딩 회사가 ",["거래소","centralized-exchange"],"나 코인 프로젝트와 계약을 맺고 시장을 조성하는 경우가 많습니다. 덕분에 ",["호가창","order-book"],"이 두꺼워지고 스프레드가 좁아져 일반 이용자의 거래 비용이 줄어듭니다."],[["탈중앙화 거래소","dex"],"에서는 AMM이라는 자동화된 규칙과 유동성 공급자가 마켓메이커 역할을 대신합니다. 한편 마켓메이커가 갑자기 호가를 거둬들이면 유동성이 순식간에 줄어 가격이 크게 튈 수 있습니다."]],"example":"어떤 코인의 현재가가 10.00달러일 때 마켓메이커가 9.99달러에 1,000개 매수, 10.01달러에 1,000개 매도 주문을 걸어 두었다고 가정해 보겠습니다. 누군가 시장가로 1,000개를 팔면 마켓메이커는 9.99달러에 사고, 곧이어 다른 사람이 1,000개를 사면 10.01달러에 팝니다. 가격이 그대로라면 1,000 × 0.02 = 20달러의 스프레드 수익이 생깁니다. 하지만 사들인 직후 가격이 9.80달러로 떨어지면 재고에서 손실이 납니다.","mistakes":["마켓메이커가 가격 방향을 정해 시장을 움직인다고 단정하지만, 기본 목적은 스프레드와 수수료 수익입니다.","호가가 두꺼워 보이면 언제나 그 물량이 유지된다고 믿지만, 급변 구간에는 호가가 순식간에 빠질 수 있습니다.","메이커 주문을 넣는 일반 트레이더와 전문 마켓메이커를 같은 개념으로 혼동합니다."],"faq":[{"q":"마켓메이커는 어떻게 돈을 버나요?","a":"매수·매도 호가의 차이인 스프레드, 거래소가 주는 메이커 리베이트나 수수료 할인이 주된 수익원입니다. 대신 보유 재고의 가격 변동 위험을 떠안습니다."},{"q":"개인도 마켓메이커가 될 수 있나요?","a":"지정가 주문으로 양쪽 호가를 거는 것 자체는 누구나 할 수 있습니다. 다만 전문 마켓메이커는 빠른 시스템과 큰 자본, 거래소와의 별도 계약을 바탕으로 운영합니다."}],"title":"마켓메이커(시장 조성자)란? 역할과 수익 구조","description":"마켓메이커가 어떻게 호가를 걸어 유동성을 공급하는지, 스프레드로 수익을 내는 방식과 위험을 설명합니다.","related":[["liquidity","유동성(Liquidity)","유동성은 원하는 수량의 자산을 가격을 크게 움직이지 않고 빠르게 사고팔 수 있는 정도를 뜻하며, 호가창의 두께와 스프레드로 확인할 수 있습니다."],["bid-ask-spread","스프레드(Bid-Ask Spread)","스프레드는 호가창에서 가장 높은 매수 호가(bid)와 가장 낮은 매도 호가(ask) 사이의 가격 차이로, 즉시 사고팔 때 부담하는 숨은 거래 비용입니다."],["maker-taker-fees","메이커·테이커 수수료(Maker/Taker Fee)","메이커·테이커 수수료는 호가창에 새 주문을 걸어 유동성을 공급한 쪽(메이커)과 이미 걸린 주문을 즉시 체결한 쪽(테이커)에 서로 다르게 매기는 거래 수수료입니다."],["order-book","호가창(Order Book)","호가창은 거래소에 걸려 있는 매수 주문과 매도 주문을 가격별로 정리해 보여 주는 목록으로, 시장의 대기 물량과 유동성을 한눈에 볼 수 있게 해 줍니다."],["amm","자동화 마켓 메이커(AMM)","자동화 마켓 메이커(AMM)는 매수자와 매도자를 호가창에서 맞추는 대신 유동성 풀에 쌓인 두 토큰의 비율과 수학 공식으로 가격을 자동으로 정하는 거래 방식입니다."]],"lesson":null,"coin":null,"tool":null,"cta":false},"risk-reward-ratio":{"slug":"risk-reward-ratio","cat":"trading","en":"Risk-reward ratio","contentLocale":"ko","term":"손익비(Risk-Reward Ratio)","aka":["리스크 리워드","RR","손익 비율"],"short":"손익비는 한 번의 거래에서 감수하는 손실 폭(진입가와 손절가의 차이)과 기대하는 수익 폭(진입가와 익절가의 차이)을 비교한 비율입니다.","body":["예를 들어 100을 잃을 위험을 지고 300을 노린다면 손익비는 1 대 3입니다. 손익비가 높을수록 승률이 낮아도 전체 수익을 낼 수 있습니다.","손익비와 승률은 함께 봐야 합니다. 1 대 1 손익비라면 승률이 50%를 넘어야 수수료를 빼고 이익이 남고, 1 대 3이라면 이론상 승률 25%를 넘으면 손익분기점을 넘습니다.",["손익비는 진입 전에 정하는 계획입니다. 익절 목표를 현실성 없이 멀리 잡으면 숫자만 좋고 실제로는 도달하지 못하는 경우가 많으므로, ",["지지선과 저항선","support-and-resistance"]," 같은 근거를 바탕으로 목표를 정합니다. ",["OCO 주문","oco-order"],"을 쓰면 손절과 익절을 한 번에 걸어 둘 수 있습니다."]],"example":["BTC를 62,000 USDT에 매수하고 손절을 61,000 ",["USDT","usdt"],", 익절을 65,000 USDT에 둔다고 가정해 보겠습니다. 손실 폭은 1,000 USDT, 수익 폭은 3,000 USDT로 손익비는 1 대 3입니다. 이런 거래를 10번 해서 3번 익절, 7번 손절했다면 수익은 3 × 3,000 = 9,000, 손실은 7 × 1,000 = 7,000으로 1 ",["BTC","bitcoin"]," 기준 2,000 USDT가 남습니다. 승률이 30%여도 이익이 나는 구조입니다."],"mistakes":["진입한 뒤 가격이 불리하게 움직이자 손절가를 더 멀리 옮겨 계획한 손익비를 스스로 망가뜨립니다.","손익비만 보고 승률과 수수료를 함께 계산하지 않습니다.","근거 없이 익절 목표를 멀리 잡아 숫자상 손익비만 높이고 실제로는 거의 도달하지 못합니다."],"faq":[{"q":"좋은 손익비는 얼마인가요?","a":"많은 트레이더가 최소 1 대 2 이상을 기준으로 삼지만, 정답은 자신의 승률과 매매 방식에 따라 다릅니다. 승률이 높은 전략은 낮은 손익비로도 수익을 낼 수 있습니다."},{"q":"손익비 1 대 3이면 승률이 얼마여야 하나요?","a":"수수료를 무시하면 승률 25%가 손익분기점입니다. 실제로는 수수료와 슬리피지 때문에 그보다 조금 높은 승률이 필요합니다."}],"title":"손익비란? 승률과 함께 계산하는 법","description":"손익비(리스크 리워드)의 뜻, 승률과의 관계, 손절·익절 위치로 손익비를 계산하는 방법을 예시로 설명합니다.","related":[["position-sizing","포지션 사이징(Position Sizing)","포지션 사이징은 한 번의 거래에서 잃어도 되는 금액을 먼저 정하고, 손절 거리에 맞춰 진입할 수량을 계산하는 자금 관리 방법입니다."],["stop-loss","손절 주문(Stop-Loss)","손절 주문(스탑로스)은 가격이 미리 정한 수준까지 불리하게 움직이면 자동으로 포지션을 정리해 손실을 제한하는 주문입니다."],["take-profit","익절 주문(Take-Profit)","익절 주문(테이크프로핏)은 가격이 미리 정한 목표 수준에 도달하면 자동으로 포지션을 정리해 이익을 확정하는 주문입니다."],["oco-order","OCO 주문(One-Cancels-the-Other)","OCO 주문은 두 개의 주문을 묶어 하나가 체결되면 나머지 하나가 자동으로 취소되도록 하는 주문 방식으로, 익절과 손절을 동시에 걸 때 주로 씁니다."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"얼마나 살지 결정하기 전에, 얼마를 잃을 수 있는지 먼저 정하라"},"coin":null,"tool":null,"cta":false},"futures-contract":{"slug":"futures-contract","cat":"derivatives","en":"Futures contract","contentLocale":"ko","term":"선물 계약(Futures Contract)","aka":["선물","선물거래","futures"],"short":"선물 계약은 특정 자산을 미리 정한 가격으로 사고팔기로 약속하는 파생상품으로, 코인을 직접 보유하지 않고도 가격 상승이나 하락에 베팅할 수 있습니다.","body":[["코인 선물에서는 실제 코인을 주고받기보다 가격 차이만큼 손익을 정산하는 방식이 일반적입니다. 가격이 오를 것으로 보면 롱, 내릴 것으로 보면 ",["숏 포지션","long-and-short"],"을 잡고, 증거금을 맡겨 ",["레버리지","leverage"],"를 쓸 수 있습니다."],["코인 선물은 크게 만기가 없는 ",["무기한 선물","perpetual-futures"],"과 정해진 날짜에 정산되는 ",["만기 선물","delivery-futures"],"(분기 선물)로 나뉩니다. 증거금 통화에 따라 ",["USDT 마진 선물","usdt-margined-futures"],"과 ",["코인 마진 선물","coin-margined-futures"],"로도 구분합니다."],"레버리지 때문에 작은 가격 변동에도 손익이 크게 움직이고, 증거금이 부족해지면 강제청산을 당할 수 있습니다. 업비트, 빗썸 같은 국내 원화 거래소는 국내 이용자에게 선물 거래를 제공하지 않으며, 거래소마다 상품 이름과 계약 조건이 다르므로 계약 명세를 확인해야 합니다."],"example":"BTC가 60,000 USDT일 때 1,000 USDT 증거금으로 5배 레버리지 롱 포지션을 열면 포지션 규모는 5,000 USDT, 약 0.0833 BTC입니다. 가격이 63,000 USDT로 5% 오르면 이익은 5,000 × 5% = 250 USDT로 증거금 대비 25%입니다. 반대로 5% 떨어지면 250 USDT 손실로 증거금의 25%를 잃습니다. 수수료와 펀딩비는 계산에서 뺐습니다.","mistakes":["현물처럼 오래 버티면 된다고 생각하지만, 선물은 증거금이 부족해지면 회복을 기다리기 전에 청산됩니다.","레버리지 배수만큼 수익이 늘어나는 것만 보고 손실도 같은 배수로 커진다는 점을 놓칩니다.","무기한 선물과 만기 선물을 구분하지 않아 만기일이나 펀딩비를 예상하지 못합니다."],"faq":[{"q":"선물과 현물의 차이는 무엇인가요?","a":"현물은 코인을 실제로 사서 보유하고, 선물은 가격 변동에 대한 계약을 거래합니다. 선물은 숏 포지션과 레버리지를 쓸 수 있는 대신 청산 위험이 있습니다."},{"q":"국내 거래소에서 선물 거래를 할 수 있나요?","a":"업비트, 빗썸 같은 국내 원화 거래소는 국내 이용자에게 코인 선물을 제공하지 않습니다. 해외 거래소 이용과 관련한 규제와 세금은 바뀔 수 있으므로 현재 규정을 확인해야 합니다."}],"title":"코인 선물 계약이란? 현물과의 차이","description":"코인 선물 계약의 뜻, 롱·숏과 레버리지, 무기한 선물과 만기 선물의 차이, 청산 위험을 예시로 설명합니다.","related":[["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["delivery-futures","만기 선물(분기 선물, Delivery Futures)","만기 선물은 정해진 만기일에 계약이 종료되고 그 시점 가격으로 정산되는 선물 계약으로, 흔히 분기마다 만기가 돌아오는 분기 선물 형태로 거래됩니다."],["leverage","레버리지(Leverage)","레버리지는 맡긴 증거금보다 몇 배 큰 규모의 포지션을 거래하는 것으로, 수익과 손실이 모두 그 배수만큼 커지고 강제청산 위험도 함께 커집니다."],["margin-trading","마진 거래(Margin Trading)","마진 거래는 계좌의 자산을 증거금으로 맡기고 거래소에서 자금을 빌려 보유 자금보다 큰 규모로 사거나, 코인을 빌려 팔아 하락에 베팅하는 거래입니다."],["hedging","헤지(Hedging)","헤지는 이미 가진 포지션의 가격 변동 위험을 줄이기 위해 반대 방향으로 움직이는 포지션을 함께 잡는 위험 관리 방법입니다."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"현물과 선물: 당신이 사는 것은 같은 상품이 아니다"},"coin":null,"tool":"/topics/derivatives","cta":true},"cross-margin":{"slug":"cross-margin","cat":"derivatives","en":"Cross margin","contentLocale":"ko","term":"교차 마진(Cross Margin)","aka":["교차","크로스 마진","cross margin","교차 모드"],"short":"교차 마진은 계좌의 사용 가능한 잔고 전체를 여러 포지션이 함께 증거금으로 쓰는 방식으로, 청산가는 멀어지지만 한 번 청산되면 계좌 잔고 대부분을 잃을 수 있습니다.","body":["교차 마진에서는 한 포지션에 손실이 나면 계좌의 남은 잔고가 자동으로 그 손실을 메웁니다. 다른 포지션의 평가 이익도 증거금으로 쓰여 서로 버팀목이 됩니다.",["덕분에 ",["격리 마진","isolated-margin"],"보다 ",["청산가","liquidation-price"],"가 진입가에서 멀어지고, ",["롱과 숏","long-and-short"],"을 함께 들고 있는 ",["헤지","hedging"]," 포지션에서는 증거금을 효율적으로 쓸 수 있습니다. 숙련된 트레이더나 여러 포지션을 동시에 관리하는 경우 많이 씁니다."],["대신 손실 한도가 보이지 않는다는 점이 위험합니다. 한 종목이 급락하면 계좌 전체 잔고가 그 손실을 메우다가 함께 청산될 수 있습니다. ",["통합 계정","unified-trading-account"],"이나 ",["포트폴리오 마진","portfolio-margin"],"은 교차 마진을 더 넓게 확장한 형태입니다."]],"example":"계좌에 3,000 USDT가 있고 교차 마진으로 ETH 롱 15,000 USDT 규모(5배)를 열었다고 가정해 보겠습니다. 유지 증거금을 75 USDT라고 하면, 손실이 3,000 − 75 = 2,925 USDT에 이를 때 청산됩니다. 이는 ETH가 약 19.5% 떨어져야 하는 수준입니다. 같은 포지션을 격리 마진 1,000 USDT로 열었다면 약 6% 하락에 청산되지만, 잃는 돈은 1,000 USDT로 제한됩니다.","mistakes":["청산가가 멀어 보인다는 이유로 손절 없이 포지션을 들고 가다가 계좌 전체를 잃습니다.","이익 난 포지션을 먼저 닫으면 증거금 여유가 줄어 다른 포지션의 청산가가 가까워진다는 점을 놓칩니다.","계좌에 장기 보유용 자금을 같이 두어 단기 선물 손실이 그 자금까지 끌어갑니다."],"faq":[{"q":"교차 마진은 왜 청산가가 더 먼가요?","a":"포지션에 배정된 증거금뿐 아니라 계좌의 사용 가능한 잔고 전체가 손실을 메우기 때문입니다. 대신 그만큼 잃을 수 있는 금액도 커집니다."},{"q":"교차 마진을 안전하게 쓰는 방법이 있나요?","a":"선물 계좌에는 잃어도 감당할 수 있는 금액만 두고, 포지션마다 손절가를 정해 두는 것이 기본입니다. 장기 보유 자산은 별도 계좌나 지갑에 분리합니다."}],"title":"교차 마진이란? 격리 마진과 무엇이 다를까","description":"교차 마진의 뜻, 계좌 잔고 전체가 증거금이 되는 원리, 격리 마진과 청산가 비교, 사용 시 주의점을 설명합니다.","related":[["isolated-margin","격리 마진(Isolated Margin)","격리 마진은 포지션마다 증거금을 따로 배정해, 그 포지션이 청산되더라도 배정한 증거금만 잃고 계좌의 나머지 잔고는 영향을 받지 않는 마진 방식입니다."],["portfolio-margin","포트폴리오 마진(Portfolio Margin)","포트폴리오 마진은 개별 포지션이 아니라 계좌 전체 포지션의 순위험을 계산해 필요한 증거금을 정하는 방식으로, 서로 상쇄되는 포지션이 많을수록 증거금 부담이 줄어듭니다."],["unified-trading-account","통합 거래 계정(UTA)","통합 거래 계정은 현물, 선물, 옵션 거래를 하나의 계정 잔고와 증거금으로 함께 운용할 수 있게 묶은 거래소 계정 방식입니다."],["liquidation","강제청산(Liquidation)","강제청산은 레버리지 포지션의 손실로 증거금이 유지 증거금 아래로 떨어졌을 때 거래소가 더 큰 손실을 막기 위해 포지션을 강제로 정리하는 것입니다."]],"lesson":{"id":"E22","slug":"cross-margin","ep":22,"title":"교차 마진: 한 포지션의 손실이 다른 포지션까지 위협하는 이유"},"coin":null,"tool":null,"cta":false},"long-and-short":{"slug":"long-and-short","cat":"derivatives","en":"Long and short positions","contentLocale":"ko","term":"롱과 숏(Long and Short)","aka":["롱","숏","롱 포지션","숏 포지션"],"short":"롱은 가격이 오를 것으로 보고 매수해 상승 시 이익을 얻는 포지션이고, 숏은 가격이 내릴 것으로 보고 매도해 하락 시 이익을 얻는 포지션입니다.","body":[[["현물 거래","spot-trading"],"에서는 코인을 사는 것 자체가 롱입니다. 숏은 보유하지 않은 코인을 먼저 팔아야 하므로, 보통 선물이나 ",["마진 거래","margin-trading"],"에서 포지션을 엽니다."],["선물에서는 롱과 숏 모두 같은 방식으로 증거금을 맡기고 ",["레버리지","leverage"],"를 쓸 수 있습니다. 롱은 가격이 0이 되면 최대 손실이 정해지지만, 숏은 가격이 오를수록 손실이 계속 커지므로 손절 관리가 특히 중요합니다."],["많은 ",["거래소","centralized-exchange"],"에서 한 방향만 들 수 있는 단방향 모드와, 같은 종목에서 롱과 숏을 동시에 들 수 있는 양방향(",["헤지","hedging"],") 모드를 선택할 수 있습니다. 모드에 따라 반대 주문이 기존 포지션을 줄이는지 새 포지션을 여는지가 달라집니다."]],"example":["BTC가 66,000 USDT일 때 0.1 ",["BTC","bitcoin"]," 롱과 0.1 BTC 숏을 각각 다른 계좌에서 열었다고 가정해 보겠습니다. BTC가 69,300 USDT로 5% 오르면 롱은 0.1 × 3,300 = 330 USDT 이익, 숏은 330 USDT 손실입니다. 반대로 62,700 USDT로 5% 떨어지면 롱이 330 USDT 손실, 숏이 330 USDT 이익입니다. 수수료와 펀딩비는 빼고 계산했습니다."],"mistakes":["양방향 모드에서 숏 주문을 넣으면 롱이 줄어든다고 생각했다가 롱과 숏을 동시에 들게 됩니다.","숏은 손실 한도가 없다는 점을 잊고 급등 구간에서 손절 없이 버팁니다.","롱과 숏의 펀딩비 방향이 반대라는 점을 놓쳐 보유 비용을 잘못 예상합니다."],"faq":[{"q":"롱과 숏은 어떻게 이익을 내나요?","a":"롱은 싸게 사서 비싸게 팔 때, 숏은 비싸게 먼저 팔고 싸게 다시 살 때 이익이 납니다. 손익은 진입가와 청산가의 차이에 수량을 곱해 계산합니다."},{"q":"현물에서도 숏을 할 수 있나요?","a":"일반 현물 매수로는 숏을 할 수 없고, 코인을 빌려 파는 현물 마진이나 선물을 이용해야 합니다. 국내 원화 거래소는 이런 상품을 국내 이용자에게 제공하지 않습니다."}],"title":"롱과 숏이란? 코인 롱·숏 포지션 뜻","description":"코인 거래의 롱과 숏 포지션 뜻, 상승·하락 시 손익 계산, 단방향과 양방향 모드의 차이를 예시로 설명합니다.","related":[["short-selling","공매도(Short Selling)","공매도는 보유하지 않은 자산을 빌리거나 계약으로 먼저 팔고, 가격이 내려간 뒤 더 싸게 사서 갚아 그 차이만큼 이익을 얻는 거래 방식입니다."],["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["leverage","레버리지(Leverage)","레버리지는 맡긴 증거금보다 몇 배 큰 규모의 포지션을 거래하는 것으로, 수익과 손실이 모두 그 배수만큼 커지고 강제청산 위험도 함께 커집니다."],["long-short-ratio","롱숏 비율(Long/Short Ratio)","롱숏 비율은 특정 거래소나 시장에서 롱 포지션을 가진 계정 또는 롱 포지션 규모가 숏에 비해 얼마나 많은지를 나타내는 투자 심리 지표입니다."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"현물과 선물: 당신이 사는 것은 같은 상품이 아니다"},"coin":null,"tool":null,"cta":true},"short-selling":{"slug":"short-selling","cat":"derivatives","en":"Short selling","contentLocale":"ko","term":"공매도(Short Selling)","aka":["숏 셀링","숏","short selling","공매도 거래"],"short":"공매도는 보유하지 않은 자산을 빌리거나 계약으로 먼저 팔고, 가격이 내려간 뒤 더 싸게 사서 갚아 그 차이만큼 이익을 얻는 거래 방식입니다.","body":[["코인 시장에서 공매도는 크게 두 가지 방식으로 합니다. 현물 마진에서 코인을 빌려 팔고 나중에 사서 갚는 방식, 그리고 선물에서 ",["숏 포지션","long-and-short"],"을 여는 방식입니다. 개인 트레이더는 대부분 선물 숏을 씁니다."],["공매도의 이익은 가격이 0이 되는 경우로 한정되지만, 손실은 가격이 오르는 만큼 계속 커질 수 있습니다. 현물 마진에서는 빌린 코인에 이자가 붙고, ",["무기한 선물","perpetual-futures"],"에서는 ",["펀딩비","funding-rate"],"가 마이너스일 때 숏이 비용을 냅니다."],[["하락장","bear-market"],"에서 이익을 내는 수단일 뿐 아니라, 보유 코인의 가격 하락 위험을 줄이는 ",["헤지","hedging"]," 수단으로도 쓰입니다. 공매도 포지션이 한쪽에 몰리면 가격 반등 시 ",["숏 스퀴즈","short-squeeze"],"로 손실이 빠르게 커질 수 있습니다."]],"example":"현물 마진에서 SOL 50개를 빌려 160 USDT에 팔아 8,000 USDT를 받았다고 가정해 보겠습니다. 일주일 뒤 SOL이 140 USDT로 떨어지면 50개를 7,000 USDT에 사서 갚고 1,000 USDT가 남습니다. 빌린 기간 이자가 하루 0.05%라면 8,000 × 0.05% × 7 = 28 USDT를 빼 순이익은 972 USDT입니다. 반대로 180 USDT로 오르면 1,000 USDT에 이자를 더한 손실이 납니다.","mistakes":["가격이 이미 많이 떨어졌으니 더 떨어질 것이라고만 보고 반등 시 손절 기준을 두지 않습니다.","현물 마진 공매도의 차입 이자나 선물 숏의 펀딩비를 계산하지 않습니다.","숏이 과도하게 몰린 상황에서 추격 공매도를 해 숏 스퀴즈에 휘말립니다."],"faq":[{"q":"코인 공매도는 어떻게 하나요?","a":"해외 거래소의 선물에서 숏 포지션을 열거나, 현물 마진에서 코인을 빌려 파는 방식이 일반적입니다. 국내 원화 거래소는 공매도 기능을 제공하지 않습니다."},{"q":"공매도의 최대 손실은 얼마인가요?","a":"이론상 가격 상승에 한도가 없으므로 손실도 한도가 없습니다. 실제로는 청산 시스템이 증거금 범위에서 포지션을 정리하므로 손절가와 레버리지 관리가 중요합니다."}],"title":"코인 공매도란? 숏 포지션 원리와 위험","description":"코인 공매도의 뜻, 현물 마진과 선물 숏 방식의 차이, 이자와 펀딩비 비용, 손실 위험을 예시로 설명합니다.","related":[["long-and-short","롱과 숏(Long and Short)","롱은 가격이 오를 것으로 보고 매수해 상승 시 이익을 얻는 포지션이고, 숏은 가격이 내릴 것으로 보고 매도해 하락 시 이익을 얻는 포지션입니다."],["perpetual-futures","무기한 선물(Perpetual Futures)","무기한 선물은 만기일 없이 원하는 만큼 포지션을 유지할 수 있는 선물 계약으로, 펀딩비를 주고받아 가격이 현물 가격 근처에 머물도록 설계되어 있습니다."],["margin-trading","마진 거래(Margin Trading)","마진 거래는 계좌의 자산을 증거금으로 맡기고 거래소에서 자금을 빌려 보유 자금보다 큰 규모로 사거나, 코인을 빌려 팔아 하락에 베팅하는 거래입니다."],["short-squeeze","숏 스퀴즈(Short Squeeze)","숏 스퀴즈는 숏 포지션이 많이 쌓인 상태에서 가격이 오르자 숏 보유자들의 손절과 강제청산이 연쇄적으로 매수 주문을 만들어 가격이 급등하는 현상입니다."]],"lesson":{"id":"E18","slug":"spot-vs-futures","ep":18,"title":"현물과 선물: 당신이 사는 것은 같은 상품이 아니다"},"coin":null,"tool":null,"cta":false},"futures-basis":{"slug":"futures-basis","cat":"derivatives","en":"Futures basis","contentLocale":"ko","term":"베이시스(Futures Basis)","aka":["선물 베이시스","basis","선물 프리미엄"],"short":"베이시스는 선물 가격과 현물 가격의 차이로, 선물이 현물보다 비싸면 플러스(콘탱고), 싸면 마이너스(백워데이션)라고 부릅니다.","body":[["베이시스는 보통 선물 가격 − 현물(지수) 가격으로 계산하고, 비교하기 쉽게 현물 대비 퍼센트나 연환산 수익률로 표시합니다. ",["만기 선물","delivery-futures"],"에서는 만기가 다가올수록 베이시스가 0에 가까워집니다."],[["강세장","bull-market"],"에서는 ",["레버리지","leverage"]," 롱 수요가 많아 선물이 현물보다 비싸게 거래되며 베이시스가 커지는 경우가 많습니다. ",["약세장","bear-market"],"이나 공포 구간에는 베이시스가 줄거나 마이너스가 되기도 합니다."],["현물을 사고 같은 양의 만기 선물을 파는 캐시 앤 캐리 거래는 만기 시점에 베이시스만큼을 확정하는 전략입니다. ",["무기한 선물","perpetual-futures"],"에서는 만기가 없어 베이시스가 ",["펀딩비","funding-rate"],"를 통해 조정됩니다."]],"example":"BTC 현물이 80,000 USDT이고 만기까지 90일 남은 분기 선물이 81,600 USDT라고 가정해 보겠습니다. 베이시스는 1,600 USDT, 현물 대비 2%입니다. 이를 연환산하면 2% × 365 ÷ 90 ≈ 8.1%입니다. 현물 1 BTC를 사고 선물 1 BTC를 숏으로 잡으면 만기에 약 1,600 USDT를 확정할 수 있지만, 거래 수수료와 선물 증거금으로 묶이는 자금 비용을 빼야 실제 수익률이 나옵니다.","mistakes":["베이시스 연환산 수익률을 확정 수익으로 보고 수수료와 증거금 비용을 계산하지 않습니다.","만기 전에 포지션을 닫으면 그 시점의 베이시스로 손익이 바뀐다는 점을 놓칩니다.","선물 숏의 증거금을 부족하게 두어 만기 전에 급등으로 청산될 수 있다는 위험을 무시합니다."],"faq":[{"q":"콘탱고와 백워데이션은 무엇인가요?","a":"선물이 현물보다 비싼 상태를 콘탱고, 싼 상태를 백워데이션이라고 합니다. 코인 시장에서는 콘탱고가 더 흔하지만 급락 구간에는 백워데이션도 나타납니다."},{"q":"베이시스와 펀딩비는 어떤 관계인가요?","a":"둘 다 선물과 현물의 가격 차이를 반영합니다. 만기 선물은 베이시스가 만기에 수렴하고, 무기한 선물은 펀딩비가 그 차이를 줄이는 역할을 합니다."}],"title":"선물 베이시스란? 콘탱고와 계산법","description":"선물 베이시스의 뜻, 콘탱고와 백워데이션, 연환산 베이시스 계산법과 캐시 앤 캐리 전략을 예시로 설명합니다.","related":[["delivery-futures","만기 선물(분기 선물, Delivery Futures)","만기 선물은 정해진 만기일에 계약이 종료되고 그 시점 가격으로 정산되는 선물 계약으로, 흔히 분기마다 만기가 돌아오는 분기 선물 형태로 거래됩니다."],["funding-rate","펀딩비(Funding Rate)","펀딩비는 무기한 선물에서 롱과 숏 포지션 보유자가 일정 간격마다 서로 주고받는 비용으로, 선물 가격이 현물 가격에서 크게 벗어나지 않도록 하는 장치입니다."],["index-price","지수 가격(Index Price)","지수 가격은 여러 주요 현물 거래소의 가격을 가중 평균해 만든 기준 가격으로, 선물의 마크 가격과 펀딩비를 계산하는 바탕이 됩니다."],["funding-rate-arbitrage","펀딩비 차익거래(Funding Rate Arbitrage)","펀딩비 차익거래는 현물을 사고 같은 양의 무기한 선물을 숏으로 잡아 가격 방향 위험을 상쇄한 채, 숏 포지션이 받는 펀딩비를 수익으로 얻는 전략입니다."]],"lesson":null,"coin":null,"tool":"/funding-rates","cta":false},"blockchain-network":{"slug":"blockchain-network","cat":"wallets-security","en":"Deposit network (chain selection)","contentLocale":"ko","term":"입금 네트워크(체인 선택)","aka":["네트워크 선택","체인 선택","전송 네트워크","deposit network"],"short":"입금 네트워크는 같은 코인을 어떤 블록체인으로 보낼지 고르는 설정으로, 보내는 쪽과 받는 쪽의 네트워크가 반드시 같아야 합니다.","body":[[["USDT","usdt"]," 하나만 봐도 ",["이더리움","ethereum"],"(ERC-20), 트론(TRC-20), BNB 스마트 체인(BEP-20), 솔라나, 아비트럼 등 여러 체인에서 발행됩니다. 이름은 같은 USDT라도 체인이 다르면 서로 다른 장부에 기록된 별개의 토큰입니다."],[["거래소","centralized-exchange"]," 출금 화면에서 네트워크를 고르면 수수료와 도착 시간이 달라집니다. 이더리움 ",["메인넷","layer-1"],"은 보통 수수료가 비싸고, 트론이나 일부 ",["레이어2","layer-2"],"는 상대적으로 저렴한 편입니다. 다만 수수료는 시점과 거래소마다 다르니 출금 화면에서 직접 확인해야 합니다."],"가장 흔한 사고는 받는 쪽이 지원하지 않는 네트워크로 보내는 것입니다. 받는 거래소 입금 화면에서 지원 네트워크를 먼저 확인하고, 보내는 쪽에서 똑같은 네트워크를 선택하는 순서가 안전합니다."],"example":["A 거래소에서 B 거래소로 1,000 USDT를 옮긴다고 가정합니다. B 거래소 입금 화면이 TRC-20과 ERC-20을 지원하고, A 거래소 ",["출금 수수료","withdrawal-fee"],"가 TRC-20은 1 USDT, ERC-20은 5 USDT라고 해 보겠습니다. TRC-20을 고르면 999 USDT, ERC-20을 고르면 995 USDT가 도착합니다. 만약 B 거래소가 지원하지 않는 BEP-20으로 보내면 1,000 USDT가 입금 처리되지 않고 별도 복구 절차가 필요하거나 찾지 못할 수 있습니다."],"mistakes":["주소 형식이 같다는 이유로 받는 쪽이 지원하지 않는 EVM 체인을 선택합니다.","수수료만 보고 네트워크를 고르고 받는 쪽 지원 여부는 확인하지 않습니다.","토큰 이름이 같으면 어느 체인에서 오든 같은 자산이라고 생각합니다."],"faq":[{"q":"USDT를 다른 네트워크로 잘못 보내면 어떻게 되나요?","a":"받는 쪽이 그 네트워크를 지원하지 않으면 잔고에 반영되지 않습니다. 거래소에 따라 수수료를 받고 복구해 주기도 하지만 보장되지 않습니다."},{"q":"어떤 네트워크를 고르는 것이 좋나요?","a":"받는 쪽이 지원하는 네트워크 가운데 수수료와 속도가 적당한 것을 고르면 됩니다. 처음 쓰는 경로라면 소액 테스트 송금을 먼저 하는 것이 안전합니다."}],"title":"입금 네트워크란? 코인 송금 체인 선택법","description":"같은 코인이라도 체인이 다르면 왜 다른 자산인지, 입금 네트워크를 고르는 순서와 잘못 보냈을 때의 문제를 설명합니다.","related":[["wallet-address","지갑 주소(Wallet Address)","지갑 주소는 블록체인에서 코인을 받을 때 쓰는 문자열로, 은행 계좌번호처럼 다른 사람에게 알려 줘도 되는 수신용 식별자입니다."],["memo-tag","메모·데스티네이션 태그(Memo/Tag)","메모(태그)는 거래소처럼 여러 사용자가 하나의 입금 주소를 함께 쓸 때 어느 계정의 입금인지 구분하기 위해 주소와 함께 입력하는 번호나 문자입니다."],["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."],["withdrawal-fee","출금 수수료","출금 수수료는 거래소에서 코인을 외부 지갑이나 다른 거래소로 보낼 때 출금 수량에서 차감되는 비용으로, 코인과 네트워크마다 다르게 정해집니다."],["transaction-hash","트랜잭션 해시(TxID)","트랜잭션 해시(TxID)는 블록체인에 기록된 거래 하나하나에 붙는 고유한 식별 문자열로, 송금이 실제로 처리됐는지 추적할 때 사용합니다."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"코인 전송 전: 이 항목들은 절대 어림짐작하지 마세요"},"coin":null,"tool":null,"cta":false},"mempool":{"slug":"mempool","cat":"onchain","en":"Mempool","contentLocale":"ko","term":"멤풀(Mempool)","aka":["메모리 풀","Mempool","대기 거래"],"short":"멤풀은 블록에 아직 포함되지 않은 거래들이 노드마다 대기하는 공간으로, 채굴자나 검증자가 여기서 거래를 골라 블록을 만듭니다.","body":[["지갑에서 거래를 보내면 바로 블록에 들어가지 않습니다. 먼저 네트워크의 ",["노드","node"],"들에게 퍼져 각 노드의 멤풀에 저장됩니다. ",["채굴","mining"],"자나 ",["검증자","validator"],"는 블록 공간이 한정되어 있으므로 보통 수수료가 높은 거래부터 골라 담습니다."],["그래서 네트워크가 붐비면 멤풀에 대기 거래가 쌓이고, 수수료를 낮게 낸 거래는 몇 시간 이상 기다릴 수 있습니다. ",["비트코인","bitcoin"],"에서는 RBF(수수료 올려 다시 보내기)나 CPFP 같은 방법으로 막힌 거래를 앞당길 수 있고, ",["이더리움","ethereum"],"에서는 같은 논스로 더 높은 ",["가스비","gas-fee"]," 거래를 다시 보내 교체합니다."],"멤풀의 거래는 공개되어 있기 때문에 다른 사람이 먼저 볼 수 있습니다. 이것을 이용해 앞서 거래를 넣는 프런트러닝, 즉 MEV가 발생합니다. 탈중앙 거래소에서 큰 스왑을 할 때 슬리피지 한도를 적절히 두는 이유입니다."],"example":"비트코인을 보낼 때 수수료를 5 sat/vB로 설정했는데, 멤풀에서 다음 블록에 들어가려면 20 sat/vB 이상이 필요하다고 가정합니다. 거래 크기가 140 vB라면 현재 수수료는 700 사토시, 필요한 수수료는 2,800 사토시입니다. RBF를 지원하는 지갑이라면 수수료를 20 sat/vB로 올려 다시 보내 추가 2,100 사토시로 대기를 줄일 수 있습니다.","mistakes":["거래가 멤풀에 있으면 이미 완료된 것으로 생각합니다.","네트워크가 붐빌 때도 최저 수수료로 보내고 급하게 기다립니다.","대기 중인 거래를 다른 주소로 다시 보내 이중 지출이 되는 줄 알고 불안해합니다. 실제로는 한쪽만 확정됩니다."],"faq":[{"q":"멤풀에 오래 머문 거래는 어떻게 되나요?","a":"수수료가 너무 낮으면 일정 시간이 지나 노드들의 멤풀에서 삭제될 수 있습니다. 그러면 자금은 원래 지갑에 그대로 남습니다."},{"q":"멤풀 상황은 어디서 보나요?","a":"비트코인은 mempool.space 같은 서비스, 이더리움은 가스 추적 도구에서 현재 대기량과 권장 수수료를 볼 수 있습니다."}],"title":"멤풀(Mempool)이란? 거래가 대기하는 이유와 수수료","description":"멤풀의 뜻, 송금이 오래 대기하는 이유, 수수료를 올려 거래를 앞당기는 방법을 계산 예시로 설명합니다.","related":[["gas-fee","가스비(Gas Fee)","가스비는 블록체인에서 송금이나 스마트 컨트랙트를 실행할 때 검증자나 채굴자에게 내는 네트워크 수수료로, 보통 그 체인의 기본 코인으로 지불합니다."],["transaction-hash","트랜잭션 해시(TxID)","트랜잭션 해시(TxID)는 블록체인에 기록된 거래 하나하나에 붙는 고유한 식별 문자열로, 송금이 실제로 처리됐는지 추적할 때 사용합니다."],["mev","MEV(최대 추출 가능 가치)","MEV는 블록 생성자나 봇이 블록 안 거래의 순서를 정하거나 끼워 넣어 얻을 수 있는 추가 이익을 말하며, 샌드위치 공격이 대표적인 예입니다."],["block-confirmations","블록 확인 수(Confirmations)","블록 확인 수는 거래가 담긴 블록 뒤에 새 블록이 몇 개 더 쌓였는지를 뜻하며, 숫자가 클수록 거래가 뒤집힐 가능성이 낮아집니다."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"전송 완료라고 뜨는데 도착하지 않았을 때, 어디를 확인해야 할까요?"},"coin":null,"tool":null,"cta":false},"no-kyc-exchange":{"slug":"no-kyc-exchange","cat":"regulation","en":"No-KYC exchange","contentLocale":"ko","term":"노KYC 거래소","aka":["무KYC 거래소","KYC 없는 거래소","No-KYC exchange"],"short":"노KYC 거래소는 신분증 인증 없이 가입하거나 일정 한도까지 거래·출금할 수 있도록 운영되는 암호화폐 거래 서비스입니다.","body":[["여기에는 성격이 다른 두 부류가 섞여 있습니다. 하나는 유니스왑이나 하이퍼리퀴드 같은 ",["탈중앙 거래소","dex"],"처럼 지갑만 연결해 쓰는 서비스이고, 다른 하나는 ",["KYC","kyc"]," 없이 소액 출금을 허용하는 ",["중앙화 거래소","centralized-exchange"],"입니다. 앞의 경우 자산을 직접 보관하지만, 뒤의 경우에는 회사가 자산을 보관합니다."],"중앙화 노KYC 거래소는 정책이 언제든 바뀔 수 있다는 점이 가장 큰 위험입니다. 처음에는 인증 없이 쓰다가 출금 금액이 커지거나 이상 거래로 분류되면 그때 KYC를 요구받는 경우가 많습니다. 또한 거주 국가 규제상 영업이 허용되지 않는 사업자일 수 있어 분쟁 시 보호를 받기 어렵습니다.",["개인정보를 덜 맡기고 싶다는 이유라면, 회사가 자산을 보관하는 방식보다 탈중앙 거래소와 ",["개인 지갑","non-custodial-wallet"],"을 쓰는 편이 구조적으로 더 일관됩니다. 그 대신 지갑 관리와 ",["스마트 컨트랙트","smart-contract"]," 위험은 스스로 책임져야 합니다."]],"example":"어떤 중앙화 거래소가 KYC 없이 하루 출금 한도를 1 BTC로 두었다고 가정합니다. 사용자가 0.4 BTC를 입금해 거래하다가 수익이 나서 잔고가 1.2 BTC가 되었습니다. 하루에 1 BTC까지만 출금되므로 남은 0.2 BTC는 다음 날을 기다려야 합니다. 그런데 그 사이 정책이 바뀌어 KYC를 요구한다면, 인증을 마치기 전까지 0.2 BTC는 묶이게 됩니다. 한도 수치는 예시이며 실제 정책은 거래소마다 다릅니다.","mistakes":["KYC가 없으니 출금도 언제나 자유롭다고 믿고 큰 금액을 맡깁니다.","탈중앙 거래소와 중앙화 노KYC 거래소의 보관 방식 차이를 구분하지 않습니다.","거주 국가에서 해당 사업자 이용이 허용되는지 확인하지 않습니다."],"faq":[{"q":"노KYC 거래소는 불법인가요?","a":"나라와 사업자 형태에 따라 다릅니다. 탈중앙 거래소 사용과 미등록 중앙화 거래소 이용은 법적 지위가 다를 수 있으므로 거주 국가 규정을 확인해야 합니다."},{"q":"KYC 없이 계속 쓸 수 있나요?","a":"중앙화 서비스는 출금 금액이나 이상 거래 감지에 따라 나중에 KYC를 요구할 수 있습니다. 처음 조건이 영구적이라고 보면 안 됩니다."}],"title":"노KYC 거래소란? 신원 인증 없는 거래소의 위험","description":"노KYC 거래소의 뜻, 탈중앙 거래소와 중앙화 무인증 거래소의 차이, 출금이 묶이는 경우를 설명합니다.","related":[["kyc","KYC(고객확인제도)","KYC는 거래소 같은 금융 서비스가 고객의 신원을 확인하고 기록하는 절차로, 자금세탁 방지 규정에 따라 계정 개설이나 입출금 전에 요구됩니다."],["dex","탈중앙화 거래소(DEX)","탈중앙화 거래소(DEX)는 회사가 자산을 보관하지 않고 사용자가 개인 지갑에서 스마트 컨트랙트와 직접 토큰을 교환하는 거래소입니다."],["withdrawal-fee","출금 수수료","출금 수수료는 거래소에서 코인을 외부 지갑이나 다른 거래소로 보낼 때 출금 수량에서 차감되는 비용으로, 코인과 네트워크마다 다르게 정해집니다."],["centralized-exchange","중앙화 거래소(CEX)","중앙화 거래소(CEX)는 회사가 운영하며 사용자의 자산을 보관하고 주문을 자체 시스템에서 체결해 주는 암호화폐 거래소입니다."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC는 어떻게 진행되며, 신분증은 누구에게 제출해야 할까요?"},"coin":null,"tool":"/topics/no-kyc","cta":false},"fiat-on-ramp":{"slug":"fiat-on-ramp","cat":"regulation","en":"Fiat on-ramp","contentLocale":"ko","term":"법정화폐 온램프(Fiat on-ramp)","aka":["온램프","원화 입금 경로","Fiat on-ramp"],"short":"법정화폐 온램프는 원화나 달러 같은 법정화폐를 암호화폐로 바꿔 시장에 처음 들어오는 경로로, 거래소 입금, 카드 결제, P2P 거래 등이 있습니다.","body":[["국내에서 가장 흔한 온램프는 실명 확인 계좌가 연결된 원화 ",["거래소","centralized-exchange"],"에 원화를 입금하고 코인을 사는 방식입니다. 해외 거래소는 카드 결제, 은행 송금, ",["P2P 거래","p2p-trading"],", 제휴 결제 업체를 통한 구매 등 여러 경로를 제공하는데, 이용 가능한 방법은 거주 국가와 거래소에 따라 다릅니다."],["경로마다 비용 구조가 다릅니다. 카드 결제는 빠르지만 수수료와 환율 ",["스프레드","bid-ask-spread"],"가 큰 편이고, 은행 송금은 느리지만 저렴한 편입니다. P2P 거래는 판매자가 제시한 가격에 이미 마진이 포함되어 있습니다. 표시된 수수료뿐 아니라 실제로 받는 코인 수량을 기준으로 비교해야 합니다."],"반대로 코인을 법정화폐로 바꿔 빠져나가는 경로는 오프램프라고 합니다. 들어갈 때 쓴 경로로 나올 수 있는지, 출금 한도와 처리 시간이 어떤지도 처음부터 확인해 두는 것이 좋습니다."],"example":["100만 원으로 USDT를 사려 한다고 가정합니다. 경로 A는 카드 결제로 수수료 3%를 떼고 1 USDT를 1,400원에 계산해 약 692.9 USDT를 줍니다. 경로 B는 계좌 이체로 수수료가 없지만 1 USDT를 1,410원에 계산해 약 709.2 USDT를 줍니다. 수수료가 없다고 표시된 B가 실제로도 약 16 ",["USDT","usdt"]," 더 많습니다. 실제 수수료와 가격은 경로와 시점마다 다릅니다."],"mistakes":["수수료 0%라는 표시만 보고 환율 스프레드를 확인하지 않습니다.","들어갈 경로만 확인하고 나중에 원화로 돌아오는 오프램프를 생각하지 않습니다.","온램프 업체를 검색 광고로 찾다가 공식처럼 꾸민 가짜 사이트에 결제합니다."],"faq":[{"q":"온램프와 오프램프의 차이는 무엇인가요?","a":"온램프는 법정화폐를 암호화폐로 바꾸는 입구이고, 오프램프는 암호화폐를 다시 법정화폐로 바꾸는 출구입니다."},{"q":"가장 저렴한 온램프는 무엇인가요?","a":"상황마다 다르므로 같은 금액을 넣었을 때 최종적으로 받는 코인 수량을 비교하는 것이 가장 정확합니다."}],"title":"법정화폐 온램프란? 원화로 코인 사는 경로 비교","description":"법정화폐 온램프의 뜻과 거래소 입금·카드·P2P 경로별 비용 차이, 실제 수령량으로 비교하는 법을 설명합니다.","related":[["p2p-trading","P2P 거래(C2C)","P2P 거래는 거래소가 중개하는 게시판에서 개인끼리 은행 이체 등 법정화폐로 대금을 주고받고 USDT 같은 코인을 사고파는 방식입니다."],["kyc","KYC(고객확인제도)","KYC는 거래소 같은 금융 서비스가 고객의 신원을 확인하고 기록하는 절차로, 자금세탁 방지 규정에 따라 계정 개설이나 입출금 전에 요구됩니다."],["centralized-exchange","중앙화 거래소(CEX)","중앙화 거래소(CEX)는 회사가 운영하며 사용자의 자산을 보관하고 주문을 자체 시스템에서 체결해 주는 암호화폐 거래소입니다."],["stablecoin","스테이블코인(Stablecoin)","스테이블코인은 미국 달러 같은 법정화폐나 다른 자산의 가치에 가격을 고정하도록 설계된 암호화폐로, USDT와 USDC가 대표적입니다."]],"lesson":{"id":"E06","slug":"first-deposit-paths","ep":6,"title":"첫 입금: 돈은 어디서 들어오고 어디로 가는 걸까요?"},"coin":null,"tool":null,"cta":true}});
